def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def get_pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            x, y = v[0], v[1]
            if isinstance(x, (int, float)) and isinstance(y, (int, float)):
                return x, y
        return default

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(src, dst):
        return [clamp_step(dst[0] - src[0]), clamp_step(dst[1] - src[1])]

    def step_away(src, dst):
        return [clamp_step(src[0] - dst[0]), clamp_step(src[1] - dst[1])]

    def center_step(src, w, h):
        return step_toward(src, (w // 2, h // 2))

    def best_target(points, src, opp=None, mode="min"):
        best = None
        best_score = None
        for p in points:
            if not isinstance(p, (list, tuple)) or len(p) < 2:
                continue
            x, y = p[0], p[1]
            if not isinstance(x, (int, float)) or not isinstance(y, (int, float)):
                continue
            d = abs(x - src[0]) + abs(y - src[1])
            score = d
            if opp is not None:
                od = abs(x - opp[0]) + abs(y - opp[1])
                score = d - 0.35 * od
            if best is None or (mode == "min" and score < best_score) or (mode == "max" and score > best_score):
                best = (x, y)
                best_score = score
        return best

    env = observation.get("environment_name", "resource_collection")
    sx, sy = get_pos(observation.get("self_position"), (0, 0))
    ox, oy = get_pos(observation.get("opponent_position"), (sx, sy))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)
    w = observation.get("grid_width", 0)
    h = observation.get("grid_height", 0)
    if not isinstance(w, int) or w <= 0:
        w = 7
    if not isinstance(h, int) or h <= 0:
        h = 7

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
        target = best_target(corners, self_pos, opp_pos, mode="max")
        if target is None:
            return step_away(self_pos, opp_pos)
        return step_toward(self_pos, target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("neutral_cells") or []
        target = best_target(targets, self_pos, opp_pos, mode="min")
        if target is not None:
            return step_toward(self_pos, target)
        return center_step(self_pos, w, h)

    resources = observation.get("resources") or observation.get("resource_cells") or observation.get("food") or []
    target = best_target(resources, self_pos, opp_pos, mode="min")
    if target is not None:
        return step_toward(self_pos, target)

    # Fallbacks: hunt if close, otherwise drift to center.
    if dist(self_pos, opp_pos) <= 2:
        return step_away(self_pos, opp_pos)
    return center_step(self_pos, w, h)

